const crypto = require("crypto");
function derivePasswordHash(password, salt) {
  return new Promise((resolve, reject) => {
    crypto.scrypt(
      String(password),
      salt,
      64,
      (error, derivedKey) => {
        if (error) {
          reject(error);
          return;
        }

        resolve(derivedKey);
      }
    );
  });
}

async function hashPassword(password) {
  const salt =
    crypto.randomBytes(16).toString("hex");

  const derivedKey =
    await derivePasswordHash(password, salt);

  return [
    "scrypt",
    salt,
    derivedKey.toString("hex")
  ].join("$");
}

function isHashedPassword(value) {
  return String(value || "").startsWith("scrypt$");
}

async function verifyHashedPassword(
  password,
  storedPassword
) {
  try {
    const parts =
      String(storedPassword || "").split("$");

    if (
      parts.length !== 3 ||
      parts[0] !== "scrypt"
    ) {
      return false;
    }

    const salt = parts[1];
    const storedKey =
      Buffer.from(parts[2], "hex");

    const suppliedKey =
      await derivePasswordHash(password, salt);

    return (
      storedKey.length === suppliedKey.length &&
      crypto.timingSafeEqual(
        storedKey,
        suppliedKey
      )
    );
  } catch (_) {
    return false;
  }
}
const { Resend } = require("resend");
const app = express();
const resend = new Resend(process.env.RESEND_API_KEY);
async function sendOrganizationNotification({
  to,
  subject,
  html,
  senderName = "Vivid",
  replyTo = "mike@vividspots.com"
}) {
  try {
    const cleanSenderName =
      String(senderName || "Vivid")
        .replace(/[\r\n<>"]/g, "")
        .trim() || "Vivid";

    const { data, error } = await resend.emails.send({
      from:
        `${cleanSenderName} <notifications@vividspots.com>`,

      to,

      replyTo,

      subject,

      html
    });

    if (error) {
      console.error(
        "ORGANIZATION NOTIFICATION ERROR:",
        error
      );

      return false;
    }

    console.log(
      "ORGANIZATION NOTIFICATION SENT:",
      data
    );

    return true;

  } catch (err) {
    console.error(
      "ORGANIZATION NOTIFICATION EXCEPTION:",
      err
    );

    return false;
  }
}
