async function getOrganizationScope(
  req,
  explicitOrganizationId = null
) {
  let organizationId = null;

  const isSuperAdmin =
  [
    "super_admin",
    "admin"
  ].includes(
    String(
      req.session.user?.role || ""
    )
      .trim()
      .toLowerCase()
  );
  

if (isSuperAdmin) {
  organizationId =
    Number(
      explicitOrganizationId
    ) ||
    Number(
      req.query.organization_id
    );
}

  if (
    !organizationId &&
    req.session.orgUser?.organization_id
  ) {
    organizationId = Number(
      req.session.orgUser.organization_id
    );
  }

  if (
    !Number.isInteger(organizationId) ||
    organizationId <= 0
  ) {
    throw new Error(
      "Valid organization is required."
    );
  }

  const organizationRole =
    isSuperAdmin
      ? "super_admin"
      : String(
          req.session.orgUser?.organization_role ||
          ""
        )
          .trim()
          .toLowerCase();

  const hasOrganizationWideAccess =
    isSuperAdmin ||
    [
      "owner",
      "organization_admin",
      "district_admin"
    ].includes(organizationRole);

  let allowedLocationIds = [];

  if (hasOrganizationWideAccess) {
    const locationsResult = await q(
      `
        SELECT id
        FROM spaces
        WHERE organization_id = $1
          AND COALESCE(is_archived, false) = false
        ORDER BY name
      `,
      [organizationId]
    );

    allowedLocationIds =
      locationsResult.rows.map(
        row => Number(row.id)
      );
  } else {
    const userId = Number(
      req.session.orgUser?.id
    );

    const locationsResult = await q(
      `
        SELECT DISTINCT
          lu.space_id AS id
        FROM location_users lu
        INNER JOIN spaces s
          ON s.id = lu.space_id
         AND s.organization_id =
             lu.organization_id
        WHERE lu.organization_id = $1
          AND lu.user_id = $2
          AND COALESCE(lu.is_active, true) = true
          AND COALESCE(s.is_archived, false) = false
        ORDER BY lu.space_id
      `,
      [
        organizationId,
        userId
      ]
    );

    allowedLocationIds =
      locationsResult.rows.map(
        row => Number(row.id)
      );
  }

  const requestedLocationId =
    req.query.location_id
      ? Number(req.query.location_id)
      : null;

  let selectedLocationId = null;

  if (
    requestedLocationId &&
    allowedLocationIds.includes(
      requestedLocationId
    )
  ) {
    selectedLocationId =
      requestedLocationId;
  }

  const dateFilter =
    getOrgDateFilter(req);

  if (dateFilter.error) {
    throw new Error(
      dateFilter.error
    );
  }

  const canEdit =
    isSuperAdmin ||
    [
      "owner",
      "organization_admin",
      "district_admin",
      "location_manager"
    ].includes(organizationRole);

  const queryString =
    new URLSearchParams();

  if (selectedLocationId) {
    queryString.set(
      "location_id",
      String(selectedLocationId)
    );
  }

  if (dateFilter.fromDate) {
    queryString.set(
      "from",
      dateFilter.fromDate
    );
  }

  if (dateFilter.toDate) {
    queryString.set(
      "to",
      dateFilter.toDate
    );
  }

  if (isSuperAdmin) {
    queryString.set(
      "organization_id",
      String(organizationId)
    );
  }

  return {
    organizationId,
    organizationRole,
    isSuperAdmin,
    hasOrganizationWideAccess,
    allowedLocationIds,
    selectedLocationId,
    fromDate:
      dateFilter.fromDate,
    toDate:
      dateFilter.toDate,
    canEdit,
    queryString:
      queryString.toString()
  };
}
async function processScheduledContractRenewals() {
  try {
    const scheduledResult = await q(`
      SELECT
        renewal.id,
        renewal.organization_id,
        renewal.renewed_from_contract_id,
        renewal.start_date,
        renewal.end_date,
        renewal.contract_name

      FROM contracts renewal

      WHERE LOWER(
        TRIM(
          COALESCE(
            renewal.status,
            ''
          )
        )
      ) = 'scheduled'

        AND renewal.start_date IS NOT NULL

        AND renewal.start_date <= CURRENT_DATE

        AND renewal.renewed_from_contract_id
            IS NOT NULL

      ORDER BY
        renewal.start_date,
        renewal.id
    `);

    let processedCount = 0;

    for (
      const renewal of
      scheduledResult.rows
    ) {
      const currentResult = await q(
        `
          SELECT
            id,
            status

          FROM contracts

          WHERE id = $1
            AND organization_id = $2

          LIMIT 1
        `,
        [
          renewal.renewed_from_contract_id,
          renewal.organization_id
        ]
      );

      const currentContract =
        currentResult.rows[0] || null;

      if (!currentContract) {
        console.error(
          "SCHEDULED RENEWAL CURRENT CONTRACT NOT FOUND:",
          renewal
        );

        continue;
      }

      await q(
        `
          UPDATE contracts

          SET
            status = 'Renewed',
            renewed_at = COALESCE(
              renewed_at,
              CURRENT_TIMESTAMP
            ),
            updated_at =
              CURRENT_TIMESTAMP

          WHERE id = $1
            AND organization_id = $2
        `,
        [
          renewal.renewed_from_contract_id,
          renewal.organization_id
        ]
      );

      await q(
        `
          UPDATE contracts

          SET
            status = 'Active',
            activated_at = COALESCE(
              activated_at,
              CURRENT_TIMESTAMP
            ),
            updated_at =
              CURRENT_TIMESTAMP

          WHERE id = $1
            AND organization_id = $2
        `,
        [
          renewal.id,
          renewal.organization_id
        ]
      );

      await q(
        `
          INSERT INTO contract_activity (
            contract_id,
            organization_id,
            user_id,
            activity_type,
            comment,
            created_at
          )

          VALUES (
            $1,
            $2,
            NULL,
            'Contract Renewed',
            'Contract term completed and scheduled renewal became active.',
            CURRENT_TIMESTAMP
          )
        `,
        [
          renewal.renewed_from_contract_id,
          renewal.organization_id
        ]
      );

      await q(
        `
          INSERT INTO contract_activity (
            contract_id,
            organization_id,
            user_id,
            activity_type,
            comment,
            created_at
          )

          VALUES (
            $1,
            $2,
            NULL,
            'Contract Activated',
            'Scheduled renewal automatically became active on its start date.',
            CURRENT_TIMESTAMP
          )
        `,
        [
          renewal.id,
          renewal.organization_id
        ]
      );

      processedCount += 1;

      console.log(
        "SCHEDULED CONTRACT RENEWAL ACTIVATED:",
        {
          new_contract_id:
            renewal.id,
          prior_contract_id:
            renewal.renewed_from_contract_id,
          organization_id:
            renewal.organization_id
        }
      );
    }

    return processedCount;

  } catch (err) {
    console.error(
      "SCHEDULED CONTRACT RENEWAL ERROR:",
      err
    );

    throw err;
  }
}
   


function requireLogin(req, res, next) {

  if (!req.session.user) {
    return res.redirect("/login");
  }

  next();
}
function requireSuperAdmin(req, res, next) {

  if (!req.session.user) {
    return res.redirect("/login");
  }

  if (req.session.user.role !== "super_admin") {
    return res.send("Access denied");
  }

  next();
}
/*
=========================================================
ADVERTISER CUSTOMER MANAGEMENT PERMISSION
=========================================================
*/

function requireAdvertiserCustomerManager(
  req,
  res,
  next
) {

  if (!req.session.user) {
    return res.redirect("/login");
  }

  const customerId =
    Number(req.params.customerId);

  if (
    !Number.isInteger(customerId) ||
    customerId <= 0
  ) {
    return res
      .status(400)
      .send(
        "Invalid Advertiser customer."
      );
  }

  const sessionUser =
    req.session.user;

  const isSuperAdmin =
    String(
      sessionUser.role || ""
    ).toLowerCase() ===
    "super_admin";

  if (isSuperAdmin) {
    return next();
  }

  const isAdvertiserUser =
  ["customer", "advertiser"].includes(
    String(
      sessionUser.role || ""
    )
      .trim()
      .toLowerCase()
  );

  const accountCustomerId =
    Number(
      sessionUser.advertiser_customer_id ||
      sessionUser.id
    );

  const actualLoginUserId =
    Number(
      sessionUser.login_user_id ||
      sessionUser.id
    );

  const isPrimaryAdvertiserUser =
    isAdvertiserUser &&
    accountCustomerId === customerId &&
    actualLoginUserId === customerId;

  if (!isPrimaryAdvertiserUser) {
    return res
      .status(403)
      .send(
        "Access denied."
      );
  }

  next();
}
function requireOrgLogin(req, res, next) {
  if (!req.session.orgUser) {
    return res.redirect("/org-login");
  }

  next();
}
