app.get(
  "/debug-latest-marketplace-space",
  requireLogin,
  async (req, res) => {
    try {
      const result = await q(`
        SELECT
          ar.id AS request_id,
          ar.organization_id,
          ar.location_id,
          ar.opportunity_id,

          o.name AS organization_name,

          s.name AS location_name,
          s.location AS market,

          oo.id AS opportunity_record_id,
          oo.title AS opportunity_title,
          oo.description AS opportunity_description,
          oo.category AS opportunity_category

        FROM organization_advertising_requests ar

        LEFT JOIN organizations o
          ON o.id = ar.organization_id

        LEFT JOIN spaces s
          ON s.id = ar.location_id

        LEFT JOIN organization_opportunities oo
          ON oo.id = ar.opportunity_id

        ORDER BY ar.id DESC

        LIMIT 1
      `);

      return res.json(result.rows[0] || null);

    } catch (err) {
      return res.status(500).send(
        "DEBUG MARKETPLACE SPACE ERROR: " + err.message
      );
    }
  }
);
app.get(
  "/debug-repair-opportunity-statuses",
  requireLogin,
  async (req, res) => {
    try {
      if (
        !req.session.user ||
        req.session.user.role !== "super_admin"
      ) {
        return res.status(403).json({
          error: "Super Admin access required"
        });
      }

      const organizationId =
        Number(req.query.organization_id);

      if (
        !Number.isInteger(organizationId) ||
        organizationId <= 0
      ) {
        return res.status(400).json({
          error:
            "A valid organization_id is required"
        });
      }

      // Reset active opportunities based on their request history.
      //
      // Priority:
      // Approved request = Approved
      // Pending request  = Pending
      // Closed request   = Closed
      // Otherwise        = Available
      //
      // Rejected requests do not remove inventory.
      const repairResult = await q(
        `
        UPDATE organization_opportunities oo
        SET
          status = CASE
            WHEN EXISTS (
              SELECT 1
              FROM organization_advertising_requests ar
              WHERE ar.organization_id = oo.organization_id
                AND ar.opportunity_id = oo.id
                AND LOWER(
                  COALESCE(ar.status, '')
                ) = 'approved'
            )
              THEN 'Approved'

            WHEN EXISTS (
              SELECT 1
              FROM organization_advertising_requests ar
              WHERE ar.organization_id = oo.organization_id
                AND ar.opportunity_id = oo.id
                AND LOWER(
                  COALESCE(ar.status, '')
                ) = 'pending'
            )
              THEN 'Pending'

            WHEN EXISTS (
              SELECT 1
              FROM organization_advertising_requests ar
              WHERE ar.organization_id = oo.organization_id
                AND ar.opportunity_id = oo.id
                AND LOWER(
                  COALESCE(ar.status, '')
                ) = 'closed'
            )
              THEN 'Closed'

            ELSE 'Available'
          END,

          updated_at = CURRENT_TIMESTAMP

        WHERE oo.organization_id = $1
          AND COALESCE(oo.is_active, true) = true

        RETURNING
          oo.id,
          oo.title,
          oo.status,
          COALESCE(
            oo.annual_price,
            oo.price,
            0
          ) AS inventory_value
        `,
        [organizationId]
      );

      const summaryResult = await q(
        `
        SELECT
          COUNT(*)::int AS total_opportunities,

          COUNT(*) FILTER (
            WHERE LOWER(
              COALESCE(status, 'available')
            ) = 'available'
          )::int AS available_opportunities,

          COUNT(*) FILTER (
            WHERE LOWER(status) = 'pending'
          )::int AS pending_opportunities,

          COUNT(*) FILTER (
            WHERE LOWER(status) = 'approved'
          )::int AS approved_opportunities,

          COUNT(*) FILTER (
            WHERE LOWER(status) = 'closed'
          )::int AS closed_opportunities,

          COALESCE(
            SUM(
              COALESCE(annual_price, price, 0)
            ),
            0
          ) AS total_inventory_value,

          COALESCE(
            SUM(
              COALESCE(annual_price, price, 0)
            ) FILTER (
              WHERE LOWER(
                COALESCE(status, 'available')
              ) = 'available'
            ),
            0
          ) AS available_inventory_value,

          COALESCE(
            SUM(
              COALESCE(annual_price, price, 0)
            ) FILTER (
              WHERE LOWER(status) = 'pending'
            ),
            0
          ) AS pending_inventory_value,

          COALESCE(
            SUM(
              COALESCE(annual_price, price, 0)
            ) FILTER (
              WHERE LOWER(status) = 'approved'
            ),
            0
          ) AS approved_inventory_value,

          COALESCE(
            SUM(
              COALESCE(annual_price, price, 0)
            ) FILTER (
              WHERE LOWER(status) = 'closed'
            ),
            0
          ) AS closed_inventory_value

        FROM organization_opportunities
        WHERE organization_id = $1
          AND COALESCE(is_active, true) = true
        `,
        [organizationId]
      );

      return res.json({
        success: true,
        organization_id: organizationId,
        repaired_count: repairResult.rows.length,
        summary: summaryResult.rows[0],
        opportunities: repairResult.rows
      });
    } catch (err) {
      console.error(
        "OPPORTUNITY STATUS REPAIR ERROR:",
        err
      );

      return res.status(500).json({
        success: false,
        error:
          "OPPORTUNITY STATUS REPAIR ERROR",
        message: err.message
      });
    }
  }
);
