/*
=========================================================
OPEN ADVERTISER CUSTOMER
=========================================================
*/

app.get(
  "/admin/advertiser-customer/:customerId",
    requireAdvertiserCustomerManager,
  async (req, res) => {
    try {

      const customerId =
        Number(req.params.customerId);

      if (
        !Number.isInteger(customerId) ||
        customerId <= 0
      ) {
        return res
          .status(400)
          .send(
            "Invalid Advertiser customer."
          );
      }

      const customerResult = await q(
        `
          SELECT
            id,
            company_name,
            name AS contact_name,
            email,
            account_status,
            created_at

          FROM users

          WHERE id = $1
            AND role = 'customer'

          LIMIT 1
        `,
        [customerId]
      );

      const customer =
        customerResult.rows[0];

      if (!customer) {
        return res
          .status(404)
          .send(
            "Advertiser customer not found."
          );
      }

      const metricsResult = await q(
        `
          SELECT

            (
              SELECT COUNT(*)::int
              FROM spaces
              WHERE user_id = $1
                AND COALESCE(
                  is_archived,
                  false
                ) = false
            ) AS location_count,

            (
              SELECT COUNT(*)::int
              FROM qr_codes qr
              JOIN spaces s
                ON s.id = qr.space_id
              WHERE s.user_id = $1
                AND COALESCE(
                  qr.is_archived,
                  false
                ) = false
            ) AS qr_count,

            (
              SELECT COUNT(*)::int
              FROM campaigns
              WHERE user_id = $1
                AND COALESCE(
                  is_archived,
                  false
                ) = false
            ) AS campaign_count
        `,
        [customerId]
      );

      const metrics =
        metricsResult.rows[0] || {};

      return res.send(
        page(
          "Advertiser Customer",
          `
            <div class="topbar">

              <div class="brand">
                Vivid Advertisers
              </div>

              <h1>
                ${escapeHtml(
                  customer.company_name ||
                  customer.email ||
                  "Advertiser Customer"
                )}
              </h1>

              <p class="subtitle">
                Advertiser customer overview.
              </p>

            </div>

            <div class="wrap">

              <div style="
                display:flex;
                gap:10px;
                flex-wrap:wrap;
                margin-bottom:24px;
              ">

                <a
                  class="btn secondary"
                  href="/admin/users?type=advertiser"
                >
                  Back to Advertisers
                </a>

              </div>

              <div
                class="cards"
                style="
                  grid-template-columns:
                    repeat(
                      3,
                      minmax(0,1fr)
                    );
                  margin-bottom:24px;
                "
              >

                <div class="card">
                  <div class="label">
                    Locations
                  </div>

                  <div class="num">
                    ${Number(
                      metrics.location_count || 0
                    )}
                  </div>
                </div>

                <div class="card">
                  <div class="label">
                    QR Placements
                  </div>

                  <div class="num">
                    ${Number(
                      metrics.qr_count || 0
                    )}
                  </div>
                </div>

                <div class="card">
                  <div class="label">
                    Active Campaigns
                  </div>

                  <div class="num">
                    ${Number(
                      metrics.campaign_count || 0
                    )}
                  </div>
                </div>

              </div>

              <div class="card">

                <h2 style="margin-top:0;">
                  Customer Information
                </h2>

                <table>

                  <tr>
                    <th>Company / Advertiser</th>
                    <th>Primary Contact</th>
                    <th>Email</th>
                    <th>Status</th>
                    <th>Created</th>
                  </tr>

                  <tr>

                    <td>
                      ${escapeHtml(
                        customer.company_name ||
                        "—"
                      )}
                    </td>

                    <td>
                      ${escapeHtml(
                        customer.contact_name ||
                        "—"
                      )}
                    </td>

                    <td>
                      ${escapeHtml(
                        customer.email ||
                        "—"
                      )}
                    </td>

                    <td>
                      ${
                        String(
                          customer.account_status ||
                          "active"
                        ).toLowerCase() ===
                        "inactive"
                          ? "Inactive"
                          : "Active"
                      }
                    </td>

                    <td>
                      ${
                        customer.created_at
                          ? new Date(
                              customer.created_at
                            ).toLocaleDateString()
                          : "—"
                      }
                    </td>

                  </tr>

                </table>

              </div>

            </div>
          `
        )
      );

    } catch (err) {

      console.error(
        "OPEN ADVERTISER CUSTOMER ERROR:",
        err
      );

      return res
        .status(500)
        .send(
          "OPEN ADVERTISER CUSTOMER ERROR: " +
          err.message
        );
    }
  }
);
/*
=========================================================
MANAGE ADVERTISER USERS
=========================================================
*/

app.get(
  "/admin/advertiser-customer/:customerId/users",
    requireAdvertiserCustomerManager,
  async (req, res) => {
    try {
      res.set("Cache-Control", "no-store, no-cache, must-revalidate, private");
      res.set("Pragma", "no-cache");
      res.set("Expires", "0");

      const customerId =
        Number(req.params.customerId);

      if (
        !Number.isInteger(customerId) ||
        customerId <= 0
      ) {
        return res
          .status(400)
          .send(
            "Invalid Advertiser customer."
          );
      }

      const customerResult = await q(
        `
          SELECT
            id,
            company_name,
            name,
            email,
            account_status

          FROM users

          WHERE id = $1
            AND role = 'customer'

          LIMIT 1
        `,
        [customerId]
      );

      const customer =
        customerResult.rows[0];

      if (!customer) {
        return res
          .status(404)
          .send(
            "Advertiser customer not found."
          );
      }

      const isActive =
        String(
          customer.account_status ||
          "active"
        ).toLowerCase() !== "inactive";
      const advertiserUsersResult =
        await q(
          `
            SELECT
              id,
              name,
              email,
              account_status,
              created_at

            FROM users

            WHERE role = 'customer'
              AND COALESCE(
                advertiser_customer_id,
                id
              ) = $1

            ORDER BY
              CASE
                WHEN id = $1
                  THEN 0
                ELSE 1
              END,
              COALESCE(
                NULLIF(
                  TRIM(name),
                  ''
                ),
                email
              )
          `,
          [customerId]
        );

      const advertiserUserRows =
        advertiserUsersResult.rows
          .map(user => {

            const userIsActive =
              String(
                user.account_status ||
                "active"
              ).toLowerCase() !==
              "inactive";

            const isPrimaryUser =
              Number(user.id) ===
              customerId;

            return `
              <tr>

                <td>
                  <strong>
                    ${escapeHtml(
                      user.name ||
                      "Unnamed User"
                    )}
                  </strong>

                  <div style="
                    color:#65776b;
                    margin-top:3px;
                  ">
                    ${escapeHtml(
                      user.email ||
                      ""
                    )}
                  </div>

                  ${
                    isPrimaryUser
                      ? `
                        <div style="
                          color:#2f855a;
                          font-size:12px;
                          font-weight:700;
                          margin-top:4px;
                        ">
                          Primary User
                        </div>
                      `
                      : ""
                  }
                </td>

                <td>
                  Advertiser User
                </td>

                <td>
                  All Advertiser Data
                </td>

                <td>
                  <span style="
                    display:inline-block;
                    padding:5px 10px;
                    border-radius:999px;
                    background:${
                      userIsActive
                        ? "#dcfce7"
                        : "#e5e7eb"
                    };
                    color:${
                      userIsActive
                        ? "#166534"
                        : "#4b5563"
                    };
                    font-weight:700;
                    font-size:12px;
                  ">
                    ${
                      userIsActive
                        ? "Active"
                        : "Inactive"
                    }
                  </span>
                </td>

                <td style="white-space:nowrap;">

                  <a
                    class="btn secondary"
                    href="/admin/advertiser-customer/${customerId}/user/${user.id}/edit"
                    style="
                      padding:8px 12px;
                      margin:0 6px 0 0;
                    "
                  >
                    Edit
                  </a>

                  <form
                    method="POST"
                    action="/admin/advertiser-customer/${customerId}/user/${user.id}/send-password-reset"
                    style="
                      display:inline;
                      margin:0 6px 0 0;
                    "
                  >
                    <button
                      class="btn secondary"
                      type="submit"
                      style="
                        padding:8px 12px;
                        margin:0;
                      "
                    >
                      Reset Password
                    </button>
                  </form>

                  ${
                    userIsActive
                      ? `
                        <form
                          method="POST"
                          action="${
                            isPrimaryUser
                              ? `/admin/advertiser-customer/${customerId}/deactivate`
                              : `/admin/advertiser-customer/${customerId}/user/${user.id}/deactivate`
                          }"
                          
                            style="${
  Number(user.id) === customerId
    ? "display:none;"
    : "display:inline;"
}margin:0;"
                            
                          
                          onsubmit="
                            return confirm(
                              'Deactivate this Advertiser user?'
                            );
                          "
                        >
                          <button
                            class="btn secondary"
                            type="submit"
                            style="
                              padding:8px 12px;
                              margin:0;
                            "
                          >
                            Deactivate
                          </button>
                        </form>
                      `
                      : `
                        <form
                          method="POST"
                          action="${
                            isPrimaryUser
                              ? `/admin/advertiser-customer/${customerId}/reactivate`
                              : `/admin/advertiser-customer/${customerId}/user/${user.id}/reactivate`
                          }"
                            style="${
  Number(user.id) === customerId
    ? "display:none;"
    : "display:inline;"
}margin:0;"
                            
                 
                          "
                        >
                          <button
                            class="btn"
                            type="submit"
                            style="
                              padding:8px 12px;
                              margin:0;
                            "
                          >
                            Reactivate
                          </button>
                        </form>
                      `
                  }

                </td>

              </tr>
            `;
          })
          .join("");
      return res.send(
        page(
          "Advertiser Users",
          `
            <div class="topbar">

              <div class="brand">
                Vivid Advertisers
              </div>

              <h1>Users</h1>

              <p class="subtitle">
                Manage who can access
                ${escapeHtml(
                  customer.company_name ||
                  customer.email ||
                  "this Advertiser account"
                )}.
              </p>

            </div>

            <div class="wrap">
              ${
                req.query.message
                  ? `
                    <div
                      class="card"
                      style="
                        padding:14px 18px;
                        margin-bottom:20px;
                        background:#e8f5eb;
                        color:#185b34;
                        font-weight:700;
                      "
                    >
                      ${escapeHtml(
                        String(
                          req.query.message
                        )
                      )}
                    </div>
                  `
                  : ""
              }
              <div style="
                display:flex;
                justify-content:space-between;
                align-items:center;
                gap:12px;
                flex-wrap:wrap;
                margin-bottom:24px;
              ">

                <a
                  class="btn secondary"
                  href="/admin/users?type=advertiser&advertiser_status=${
                    String(customer.account_status || "active").toLowerCase() === "inactive"
                      ? "archived"
                      : "active"
                  }"
                >
                  Back to Customers
                </a>

                <a
                  class="btn"
                  href="/admin/advertiser-customer/${customerId}/users/new"
                >
                  Add User
                </a>

              </div>

              <div class="card">

                <table>

                  <tr>
                    <th>User</th>
                    <th>Role</th>
                    <th>Access</th>
                    <th>Status</th>
                    <th>Action</th>
                  </tr>

                  
${advertiserUserRows}
                   
                       
                  

                </table>

              </div>

            </div>
          `
        )
      );

    } catch (err) {

      console.error(
        "MANAGE ADVERTISER USERS ERROR:",
        err
      );

      return res
        .status(500)
        .send(
          "MANAGE ADVERTISER USERS ERROR: " +
          err.message
        );
    }
  }
);
